when.set-body:
@{
        var body = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
        if ((string)body["method"] == "tools/call") {
            var parameters = body["params"] as Newtonsoft.Json.Linq.JObject;
            var name = (string)parameters?["name"];
            var arguments = parameters?["arguments"] as Newtonsoft.Json.Linq.JObject;
            if ((name == "listSystems" || name == "listDataProducts")
                && arguments?["domain"]?.Type == Newtonsoft.Json.Linq.JTokenType.String) {
                arguments["domain"] = System.Uri.EscapeDataString((string)arguments["domain"]);
            }
        }
        return body.ToString(Newtonsoft.Json.Formatting.None);
    }
